package clientimport

import "ragnarok-of-building/internal/gamedata"

// ApplyLatamTables puts the LATAM class tables of latam-ro-calc (current
// rebalance, generated by tools/latamgen/tablegen.py) over rAthena's: base
// HP/SP, stat and trait bonuses per job level, and base ASPD per weapon.
// Only the levels and weapons latam-ro-calc lists change. It returns how
// many jobs changed.
func ApplyLatamTables(c *gamedata.Catalog) int {
	n := 0
	for _, j := range c.Jobs {
		changed := false
		set := func(t []int, lv, v int) []int {
			for len(t) < lv {
				t = append(t, 0)
			}
			if t[lv-1] != v {
				t[lv-1] = v
				changed = true
			}
			return t
		}
		for lv, v := range latamBaseHP[j.Code] {
			if lv >= 1 {
				j.BaseHP = set(j.BaseHP, lv, v)
			}
		}
		for lv, v := range latamBaseSP[j.Code] {
			if lv >= 1 {
				j.BaseSP = set(j.BaseSP, lv, v)
			}
		}
		bonus := func(table map[int][6]int, off int) {
			for lv, v := range table {
				if lv < 0 {
					continue
				}
				for len(j.JobBonus) <= lv {
					j.JobBonus = append(j.JobBonus, [12]int{})
				}
				for i, x := range v {
					if j.JobBonus[lv][off+i] != x {
						j.JobBonus[lv][off+i] = x
						changed = true
					}
				}
			}
		}
		bonus(latamJobBonus[j.Code], 0)
		bonus(latamTraitBonus[j.Code], 6)
		if d := latamASPD[j.Code]; d != nil {
			if j.BaseASPD == nil {
				j.BaseASPD = map[string]int{}
			}
			for w, v := range d {
				if j.BaseASPD[w] != v {
					j.BaseASPD[w] = v
					changed = true
				}
			}
		}
		if changed {
			n++
		}
	}
	return n
}
